(4,'Account Create Success modal','account-create-success-modal','<p style=\"text-align: center;\" style=\"text-align: center;\">\n<strong>QUE DIA ESPECIAL!!</strong></p><p style=\"text-align: center;\" style=\"text-align: center;\">\n<strong>AGORA VOCÊ FAZ PARTE DA FAMÍLIA BELT NUTRITION,\nESPERAMOS TE VER MUITAS E MUITAS VEZES POR AQUI!!!</strong></p>\n<p style=\"text-align: center;\" style=\"text-align: center;\"><strong>TEMOS UM PRESENTE PARA VOCÊ: FRETE GRÁTIS\n NA PRIMEIRA COMPRA!!!</strong></p><p style=\"text-align: center;\" style=\"text-align: center;\">\n <strong>CONTE SEMPRE COM A GENTE!!</strong></p>','2025-07-10 15:24:21','2025-07-10 15:24:21',1,4,1,2147483647),
(5,'Block Alert customer area','alert-customer',NULL,'2025-07-10 15:24:21','2025-07-10 15:24:21',1,5,1,2147483647),
(6,'Resellers Footer','resellers-footer','<div class=\"footer content-resellers\">\n<div class=\"content\">\n<p>© 2020 BELT NUTRITION COMERCIO SUPLEMENTOS LTDA | CNPJ: 21.212.216/0001-90</p>\n</div>\n</div>','2025-07-10 15:24:21','2025-07-10 15:24:21',1,6,1,2147483647),
(7,'Resellers Menu','resellers-menu','<nav class=\"navigation\">\n<ul class=\"resellers-menu\">\n<li class=\"resellers-menu-opt\"><a href=\"#como-funciona\"> Como funciona? </a></li>\n<li class=\"resellers-menu-opt\"><a href=\"#cadastro\"> Faça seu cadastro </a></li>\n<li class=\"resellers-menu-opt\"><a href=\"#catalogo\"> catálogo </a></li>\n<li class=\"resellers-menu-opt\"><a href=\"#dicas\"> Dicas </a></li>\n<li class=\"resellers-menu-opt\"><a href=\"#duvidas-freq\"> dúvidas frequentes </a></li>\n</ul>\n</nav>','2025-07-10 15:24:21','2025-07-10 15:24:21',1,7,1,2147483647);
