(5,'DESDE INÍCIO BELT - Clientes Sem Compras- B2C - 28/11/24-36.193','(01/12/22 - 29.344)..(30/12 - 29.452)..(31/03/23 31.637)..(24/05 32.448) ..(10/09 34.633) (18/12 30.255) (07/03/24 31.504) (09/07/24-33.606)',1,'{\"type\":\"Magento\\\\CustomerSegment\\\\Model\\\\Segment\\\\Condition\\\\Combine\\\\Root\",\"attribute\":null,\"operator\":null,\"value\":\"1\",\"is_value_processed\":null,\"aggregator\":\"all\",\"conditions\":[{\"type\":\"Magento\\\\CustomerSegment\\\\Model\\\\Segment\\\\Condition\\\\Customer\\\\Attributes\",\"attribute\":\"group_id\",\"operator\":\"==\",\"value\":\"1\",\"is_value_processed\":false},{\"type\":\"Magento\\\\CustomerSegment\\\\Model\\\\Segment\\\\Condition\\\\Sales\\\\Ordersnumber\\\\Interceptor\",\"attribute\":\"total\",\"operator\":\"<\",\"value\":\"1\",\"is_value_processed\":null,\"aggregator\":\"all\",\"conditions\":[{\"type\":\"Magento\\\\CustomerSegment\\\\Model\\\\Segment\\\\Condition\\\\Order\\\\Status\",\"attribute\":false,\"operator\":\"==\",\"value\":\"complete\",\"is_value_processed\":false}]}]}',1,'SELECT 1 FROM `customer_entity` AS `root` WHERE ((IF((SELECT 1 FROM `customer_entity` AS `main`\n INNER JOIN `customer_entity` AS `entity_table` ON main.entity_id = entity_table.entity_id WHERE (main.entity_id = :customer_id) AND (`main`.`group_id` = \'1\') AND (entity_table.website_id = :website_id) LIMIT 1), 1, 0) = 1) AND (IF((SELECT (SELECT IF(COUNT(*) < 1, 1, 0) FROM `sales_order`\n INNER JOIN `store` ON sales_order.store_id=store.store_id WHERE (sales_order.customer_id = customer_entity.entity_id) AND (store.website_id IN (:website_id)) AND (sales_order.status = \'complete\')) FROM `customer_entity` WHERE (customer_entity.entity_id = :customer_id)), 1, 0) = 1))',1),
