(232,'teste por data',NULL,1,'{\"type\":\"Magento\\\\CustomerSegment\\\\Model\\\\Segment\\\\Condition\\\\Combine\\\\Root\",\"attribute\":null,\"operator\":null,\"value\":\"1\",\"is_value_processed\":null,\"aggregator\":\"all\",\"conditions\":[{\"type\":\"Customer\\\\LastLoginDate\",\"attribute\":false,\"operator\":\"==\",\"value\":\"2025-09-01...2025-10-13\",\"is_value_processed\":false}]}',1,'SELECT 1 FROM `customer_entity` AS `root`',0),
(233,'TESTE',NULL,1,'{\"type\":\"Magento\\\\CustomerSegment\\\\Model\\\\Segment\\\\Condition\\\\Combine\\\\Root\",\"attribute\":null,\"operator\":null,\"value\":\"1\",\"is_value_processed\":null,\"aggregator\":\"all\",\"conditions\":[{\"type\":\"Magento\\\\CustomerSegment\\\\Model\\\\Segment\\\\Condition\\\\Customer\\\\Attributes\",\"attribute\":\"email\",\"operator\":\"==\",\"value\":\"leandro.santos@beltnutrition.com.br\",\"is_value_processed\":false}]}',1,'SELECT 1 FROM `customer_entity` AS `root` WHERE ((IF((SELECT 1 FROM `customer_entity` AS `main`\n INNER JOIN `customer_entity` AS `entity_table` ON main.entity_id = entity_table.entity_id WHERE (main.entity_id = :customer_id) AND (`main`.`email` = \'leandro.santos@beltnutrition.com.br\') AND (entity_table.website_id = :website_id) LIMIT 1), 1, 0) = 1))',0);
